function gameLoop(timestamp) {
  player.x += player.vx;
  player.y += player.vy;
  render(player);
  requestAnimationFrame(gameLoop);
}

function onKeyDown(e) {
  if (e.key === "ArrowRight") player.vx = 4;
  if (e.key === "ArrowUp") player.vy = -4;
}

requestAnimationFrame(gameLoop);
